```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, metric, round(avg(value),3) v, count(*) n FROM abnormal_metrics WHERE service_name='search' AND metric IN ('container.cpu.usage') GROUP BY 1,2 ORDER BY 1", "claim": "Search container CPU usage sits at about 2.8 cores for every abnormal minute, against about 0.006 cores in the normal period."},
        {"kind": "metric", "sql": "SELECT 'n' p, metric, round(avg(value),4) v FROM normal_metrics WHERE service_name='search' AND metric='container.cpu.usage' GROUP BY 1,2 UNION ALL SELECT 'a', metric, round(avg(value),4) FROM abnormal_metrics WHERE service_name='search' AND metric='container.cpu.usage' GROUP BY 1,2", "claim": "Search container CPU averages 0.006 cores normally and 2.7 cores in the abnormal window; pod CPU matches."},
        {"kind": "metric", "sql": "SELECT 'a' p, service_name, count(DISTINCT attr_k8s_pod_name) pods FROM abnormal_metrics WHERE metric='k8s.container.ready' GROUP BY 1,2", "claim": "Pod count and container readiness are unchanged, so search's CPU rise is not a restart or replacement."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend", "evidence": [
      {"kind": "trace", "sql": "SELECT 'a' p, service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY 1,2,3,4 UNION ALL SELECT 'n', service_name, span_name, attr_span_kind, count(*), round(quantile_cont(duration,0.95)/1e6,2) FROM normal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='frontend' AND span_name='search.Search/Nearby') GROUP BY 1,2,3,4", "claim": "Search.Nearby p95 rises only slightly, from about 8.4 to 8.5 ms in search and 8.8 to 8.6 ms in frontend; the effect on the user path is small."}
    ]}
  ]
}
```

